//! Evidence for the gateway's later verification, never an authorization.
//! SKILL.md is regenerated by the importer; its source path is retained so
//! the gateway can check manifest membership and scan the quarantined copy.

use std::io::Read;
use std::path::{Component, Path, PathBuf};

use duduclaw_core::fs_safety::{is_link_metadata, open_regular_file_nofollow};
use duduclaw_core::pack::signatures::{MANIFEST, SIGNATURE};
use duduclaw_core::publishers::SignatureState;
use duduclaw_gateway::expert_skills::QuarantinedSkill;
use serde::Serialize;

use crate::expert::install::{InstallCtx, write_planned_file};

type Result<T> = std::result::Result<T, String>;

#[derive(Debug, Serialize)]
pub(super) struct SkillProvenance {
    pub agent: String,
    pub name: String,
    pub source_dir: Option<String>,
    pub files: Vec<String>,
}

fn safe_rel(path: &str) -> bool {
    !path.is_empty() && !path.contains(['\\', ':', '\r', '\n'])
        && path.split('/').all(|part| !part.is_empty() && part != "." && part != "..")
        && Path::new(path).components().all(|part| matches!(part, Component::Normal(_)))
}

pub(super) fn source_rel(root: &Path, dir: &Path) -> Option<String> {
    let rel = dir.strip_prefix(root).ok()?;
    let parts = rel.components().map(|part| match part {
        Component::Normal(name) => name.to_str(),
        _ => None,
    }).collect::<Option<Vec<_>>>()?;
    let rel = parts.join("/");
    safe_rel(&rel).then_some(rel)
}

fn check_dir(path: &Path) -> Result<()> {
    let meta = std::fs::symlink_metadata(path).map_err(|e| e.to_string())?;
    if is_link_metadata(&meta) || !meta.is_dir() {
        return Err("來源證據路徑含捷徑或非一般目錄".into());
    }
    Ok(())
}

/// Walk from the trusted home without following any link below it. Missing
/// parents mean there is no stale provenance to remove (e.g. no quarantine).
fn expert_dir(home: &Path, slug: &str) -> Result<Option<PathBuf>> {
    if !safe_rel(slug) || slug.contains('/') { return Err("無效的匯入代號".into()); }
    check_dir(home)?;
    let mut path = home.to_path_buf();
    for part in ["experts", slug] {
        path.push(part);
        match std::fs::symlink_metadata(&path) {
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(None),
            Err(e) => return Err(e.to_string()),
            Ok(meta) if is_link_metadata(&meta) || !meta.is_dir() => {
                return Err("來源證據目的地含捷徑或非一般目錄".into());
            }
            Ok(_) => {}
        }
    }
    Ok(Some(path))
}

fn read_evidence(root: &Path, name: &str, limit: u64) -> Result<Vec<u8>> {
    check_dir(root)?;
    let file = open_regular_file_nofollow(&root.join(name)).map_err(|e| e.to_string())?;
    let mut bytes = Vec::new();
    file.take(limit + 1).read_to_end(&mut bytes).map_err(|e| e.to_string())?;
    if bytes.len() as u64 > limit { return Err(format!("來源證據 {name} 過大")); }
    Ok(bytes)
}

/// Remove stale evidence first, then publish one complete private directory.
/// Any error is handled by the caller as a warning and a manual approval.
pub(super) fn replace(
    ctx: &InstallCtx,
    root: &Path,
    slug: &str,
    quarantined: &[QuarantinedSkill],
    skills: &[SkillProvenance],
) -> Result<bool> {
    let parent = expert_dir(&ctx.home, slug)?;
    if let Some(parent) = &parent {
        let dest = parent.join("provenance");
        match std::fs::symlink_metadata(&dest) {
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
            Err(e) => return Err(e.to_string()),
            Ok(meta) if is_link_metadata(&meta) || !meta.is_dir() => {
                return Err("來源證據目的地不是一般目錄".into());
            }
            // remove_dir_all does not follow links inside the old directory.
            Ok(_) => std::fs::remove_dir_all(&dest).map_err(|e| e.to_string())?,
        }
    }
    let status = match ctx.signature_status.as_ref() {
        Some(status) if status.state == SignatureState::Verified && !ctx.source_is_github => status,
        _ => return Ok(false),
    };
    if quarantined.is_empty() { return Ok(false); }
    match std::fs::symlink_metadata(root.join("pack.toml")) {
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(false),
        Err(e) => return Err(e.to_string()),
        Ok(meta) if is_link_metadata(&meta) || !meta.is_file() => return Err("pack.toml 不是一般檔案".into()),
        Ok(_) => {}
    }
    let parent = parent.ok_or("找不到隔離技能目錄")?;
    if skills.len() != quarantined.len() || skills.iter().any(|s| {
        !s.source_dir.as_deref().is_some_and(safe_rel)
            || !s.files.iter().all(|file| safe_rel(file))
            || !s.files.iter().any(|file| file == "SKILL.md")
            || s.files.windows(2).any(|pair| pair[0] >= pair[1])
            || quarantined.iter().filter(|q| q.agent == s.agent && q.name == s.name).count() != 1
    }) {
        return Err("隔離技能的來源對照不完整".into());
    }
    let manifest = read_evidence(root, MANIFEST, 2 * 1024 * 1024)?;
    let signature = read_evidence(root, SIGNATURE, 4096)?;
    let text = std::str::from_utf8(&manifest).map_err(|e| e.to_string())?;
    let mut lines = text.lines();
    let mut header = |prefix: &str| -> Result<&str> {
        lines.next().and_then(|line| line.strip_prefix(prefix)).filter(|value| !value.is_empty())
            .ok_or_else(|| format!("簽章清單表頭缺少 {prefix}"))
    };
    let pack = header("name: ")?;
    let pack_version = header("version: ")?;
    let publisher = header("publisher: ")?;
    if status.publisher.as_deref() != Some(publisher) {
        return Err("簽章清單發行者與驗證結果不同".into());
    }
    let map = serde_json::to_vec_pretty(&serde_json::json!({
        "version": 1, "publisher": publisher, "pack": pack, "pack_version": pack_version,
        "skills": skills,
    })).map_err(|e| e.to_string())?;
    let stage = tempfile::Builder::new().prefix(".provenance-").tempdir_in(&parent)
        .map_err(|e| e.to_string())?;
    #[cfg(unix)] {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(stage.path(), std::fs::Permissions::from_mode(0o700))
            .map_err(|e| e.to_string())?;
    }
    for (name, bytes) in [(MANIFEST, manifest.as_slice()), (SIGNATURE, signature.as_slice()), ("provenance.json", map.as_slice())] {
        write_planned_file(stage.path(), name, bytes).map_err(|e| e.to_string())?;
        #[cfg(unix)] {
            use std::os::unix::fs::PermissionsExt;
            open_regular_file_nofollow(&stage.path().join(name)).map_err(|e| e.to_string())?
                .set_permissions(std::fs::Permissions::from_mode(0o600)).map_err(|e| e.to_string())?;
        }
    }
    check_dir(&parent)?;
    std::fs::rename(stage.path(), parent.join("provenance")).map_err(|e| e.to_string())?;
    Ok(true)
}

#[cfg(test)]
mod tests {
    use super::*;
    use duduclaw_core::publishers::SignatureStatus;
    use duduclaw_gateway::approval::{ApprovalBroker, ApprovalId, ApprovalStatus};
    use duduclaw_gateway::expert_skills::{self, SkillsStatus};
    use crate::expert::Report;

    fn fixture() -> (tempfile::TempDir, tempfile::TempDir, InstallCtx, Vec<QuarantinedSkill>, Vec<SkillProvenance>) {
        let home = tempfile::tempdir().unwrap();
        let root = tempfile::tempdir().unwrap();
        std::fs::write(root.path().join("pack.toml"), "[pack]\n").unwrap();
        std::fs::write(root.path().join(MANIFEST), "name: team\nversion: 1.0.0\npublisher: fixture\n").unwrap();
        std::fs::write(root.path().join(SIGNATURE), "signature bytes\r\n").unwrap();
        let ctx = InstallCtx {
            home: home.path().to_path_buf(), dry_run: false, confirm_profile: None,
            signature_status: Some(SignatureStatus { state: SignatureState::Verified, publisher: Some("fixture".into()) }),
            source_is_github: false, rename: false, trust_hooks: false, attach_under: None,
            reimport: Default::default(), replace: None, agent_cap: None,
            replace_state: Default::default(), seat_admission: Default::default(),
        };
        let dir = expert_skills::quarantined_skill_dir(home.path(), "team", "worker", "helper");
        std::fs::create_dir_all(dir.join("scripts")).unwrap();
        std::fs::write(dir.join("SKILL.md"), "Help with documents.\n").unwrap();
        std::fs::write(dir.join("scripts/run.sh"), "echo hello\n").unwrap();
        let skills = vec![QuarantinedSkill {
            agent: "worker".into(), name: "helper".into(), label: String::new(),
            reasons: vec!["script".into()], needs: Vec::new(), digest: expert_skills::tree_digest(&dir).unwrap(),
        }];
        let map = vec![SkillProvenance {
            agent: "worker".into(), name: "helper".into(), source_dir: Some("skills/helper".into()),
            files: vec!["SKILL.md".into(), "scripts/run.sh".into()],
        }];
        (home, root, ctx, skills, map)
    }

    async fn assert_manual(ctx: &InstallCtx, root: &Path, skills: Vec<QuarantinedSkill>, map: &[SkillProvenance]) {
        let mut report = Report::default();
        super::super::placement::file_quarantine(ctx, root, "team", skills, map, &mut report).await;
        let state = expert_skills::read_skills_state(&ctx.home, "team").unwrap();
        assert_eq!(state.status, SkillsStatus::PendingApproval);
        let id = ApprovalId::from(state.approval_id.unwrap());
        let broker = ApprovalBroker::open(&ctx.home).unwrap();
        assert_eq!(broker.poll(&id).await.unwrap(), ApprovalStatus::Pending);
        assert!(broker.get(&id).await.unwrap().unwrap().payload.get("auto_approval_candidate").is_none());
        assert!(report.to_json(false)["items"].as_array().unwrap().iter().any(|item| {
            item["kind"] == "skill-provenance" && item["status"] == "warning"
        }));
    }

    #[tokio::test]
    async fn provenance_write_failure_still_files_manual_approval() {
        let (home, root, ctx, skills, map) = fixture();
        let dest = home.path().join("experts/team/provenance");
        std::fs::write(&dest, "obstruction").unwrap();
        assert_manual(&ctx, root.path(), skills, &map).await;
        assert_eq!(std::fs::read_to_string(dest).unwrap(), "obstruction");
    }

    #[tokio::test]
    async fn missing_signature_or_unknown_source_still_files_manual_approval() {
        for missing_signature in [true, false] {
            let (home, root, ctx, skills, mut map) = fixture();
            if missing_signature { std::fs::remove_file(root.path().join(SIGNATURE)).unwrap(); }
            else { map[0].source_dir = None; }
            assert_manual(&ctx, root.path(), skills, &map).await;
            assert!(!home.path().join("experts/team/provenance").exists());
        }
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn provenance_symlinks_are_not_followed() {
        use std::os::unix::fs::symlink;
        for linked_source in [false, true] {
            let (home, root, ctx, skills, map) = fixture();
            let outside = tempfile::tempdir().unwrap();
            std::fs::write(outside.path().join("sentinel"), "unchanged").unwrap();
            if linked_source {
                std::fs::remove_file(root.path().join(SIGNATURE)).unwrap();
                symlink(outside.path().join("sentinel"), root.path().join(SIGNATURE)).unwrap();
            } else {
                symlink(outside.path(), home.path().join("experts/team/provenance")).unwrap();
            }
            assert_manual(&ctx, root.path(), skills, &map).await;
            assert_eq!(std::fs::read_to_string(outside.path().join("sentinel")).unwrap(), "unchanged");
            assert_eq!(std::fs::read_dir(outside.path()).unwrap().count(), 1);
        }
    }

    #[test]
    fn replacing_provenance_removes_old_files_before_publishing() {
        let (home, root, ctx, skills, map) = fixture();
        assert!(replace(&ctx, root.path(), "team", &skills, &map).unwrap());
        let dest = home.path().join("experts/team/provenance");
        std::fs::write(dest.join("obsolete"), "old").unwrap();
        std::fs::write(root.path().join(SIGNATURE), "new signature bytes").unwrap();
        assert!(replace(&ctx, root.path(), "team", &skills, &map).unwrap());
        assert!(!dest.join("obsolete").exists());
        assert_eq!(std::fs::read(dest.join(SIGNATURE)).unwrap(), b"new signature bytes");
        // A failed replacement also leaves no old evidence to reuse.
        std::fs::remove_file(root.path().join(SIGNATURE)).unwrap();
        assert!(replace(&ctx, root.path(), "team", &skills, &map).is_err());
        assert!(!dest.exists());
    }

    #[test]
    fn source_paths_are_portable_and_cannot_escape_the_pack() {
        let root = Path::new("pack");
        assert!(!safe_rel("skills/a\\b"));
        assert_eq!(source_rel(root, &root.join("skills").join("說明")), Some("skills/說明".into()));
        for dir in [root.to_path_buf(), root.join("../escape"), PathBuf::from("elsewhere/skill")] {
            assert_eq!(source_rel(root, &dir), None);
        }
    }
}
